#!/usr/bin/env python3
"""Generate crates/lsaca/src/stdlib_embed.rs from the stdlib sources.

The standard library lives in stdlib/src and is written in lsaca itself. The
compiler embeds every file so a built binary never needs the sources at run
time. Run this script after adding, removing or editing a stdlib file; pass
--check to verify that the generated file is up to date (CI does this).
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
STDLIB = ROOT / "stdlib" / "src"
OUTPUT = ROOT / "crates" / "lsaca" / "src" / "stdlib_embed.rs"


def collect() -> list[tuple[str, str]]:
    files: list[tuple[str, str]] = []
    for path in sorted(STDLIB.rglob("*.ls")):
        rel = path.relative_to(STDLIB).as_posix()
        files.append((rel, "stdlib/src/" + rel))
    files.sort(key=lambda item: (item[0] != "lib.ls", item[0]))
    return files


def render(files: list[tuple[str, str]]) -> str:
    lines = [
        "//! Generated by scripts/gen_stdlib_embed.py; do not edit by hand.",
        "//!",
        "//! Every file of the standard library (stdlib/src), embedded as text so",
        "//! the compiler binary is self contained. The order puts the crate root",
        "//! lib.ls first, then the remaining files sorted by path.",
        "",
        "/// The embedded standard-library files as (path, source) pairs.",
        "#[rustfmt::skip]",
        "pub const FILES: &[(&str, &str)] = &[",
    ]
    for rel, include in files:
        lines.append('    ("%s", include_str!("../../../%s")),' % (rel, include))
    lines.append("];")
    lines.append("")
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="verify the generated file is current")
    args = parser.parse_args()
    files = collect()
    if not files:
        print("error: stdlib/src has no .ls files", file=sys.stderr)  # noqa: EM101
        return 1
    rendered = render(files)
    if args.check:
        if not OUTPUT.exists():
            print("error: %s is missing; run scripts/gen_stdlib_embed.py" % OUTPUT, file=sys.stderr)
            return 1
        current = OUTPUT.read_text(encoding="utf-8")
        if current != rendered:
            print("error: %s is out of date; run scripts/gen_stdlib_embed.py" % OUTPUT, file=sys.stderr)
            return 1
        print("stdlib_embed.rs is up to date (%d files)" % len(files))
        return 0
    OUTPUT.write_text(rendered, encoding="utf-8", newline="\n")
    print("wrote %s (%d files)" % (OUTPUT, len(files)))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
